html:
{% set co = frappe.db.get_value('Company', doc.company, ['company_name','phone_no','email','tax_id','company_logo'], as_dict=1) or {} %}
{% set co_name  = co.get('company_name') or doc.company or '' %}
{% set co_phone = co.get('phone_no') or '' %}
{% set co_email = co.get('email') or '' %}
{% set co_tax   = co.get('tax_id') or '' %}
{% set co_logo  = co.get('company_logo') or '/files/oasis_logo.png' %}
{% set addr_doc = {} %}
{% if doc.company %}
  {% set dl = frappe.db.sql("SELECT parent FROM `tabDynamic Link` WHERE link_doctype='Company' AND link_name=%s AND parenttype='Address' LIMIT 1", doc.company) %}
  {% if dl %}
    {% set addr_doc = frappe.db.get_value('Address', dl[0][0], ['address_line1','address_line2','city','state','country','pincode'], as_dict=1) or {} %}
  {% endif %}
{% endif %}
{% set cust_addr_doc = {} %}
{% if doc.customer %}
  {% set cdl = frappe.db.sql("SELECT parent FROM `tabDynamic Link` WHERE link_doctype='Customer' AND link_name=%s AND parenttype='Address' LIMIT 1", doc.customer) %}
  {% if cdl %}
    {% set cust_addr_doc = frappe.db.get_value('Address', cdl[0][0], ['address_line1','address_line2','city','state','country','pincode'], as_dict=1) or {} %}
  {% endif %}
{% endif %}
{% set current_user_name = frappe.db.get_value('User', frappe.session.user, 'full_name') or frappe.session.user %}
{% macro v(x) %}{{ x if x else '-' }}{% endmacro %}
{% macro fd(d) %}{% if d %}{{ frappe.format(d, {'fieldtype':'Date'}) }}{% else %}-{% endif %}{% endmacro %}
{% macro fc(n) %}{% if n %}{{ frappe.format(n, {'fieldtype':'Currency'}) }}{% else %}0.00{% endif %}{% endmacro %}

<style>
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap');

:root{
  --primary:#0580a3;
  --primary-dark:#046885;
  --primary-light:#f0f8fa;
  --text-main:#1f2937;
  --text-muted:#6b7280;
  --border-light:#e5e7eb;
  --bg-stripe:#f9fafb;
  --bg-card:#ffffff;
}

*{box-sizing:border-box;margin:0;padding:0;}
body,.print-format{
  font-family:'Poppins',sans-serif;
  font-size:10.5px;
  font-weight:400;
  color:var(--text-main);
  background:#ffffff;
  line-height:1.5;
}

/* ── HEADER WITH FULL BG COLOR ── */
.hdr{
  background:var(--primary);
  color:#ffffff !important;
  padding:18px 24px;
  display:flex;
  justify-content:space-between;
  align-items:center;
  border-radius:6px;
  margin-bottom:20px;
}
.hdr *, .hdr div, .hdr span{
  color:#ffffff !important;
}
.hdr-left{
  flex:1;
}
.co-logo-img{
  max-height:52px;
  max-width:200px;
  object-fit:contain;
  margin-bottom:4px;
  background:#ffffff;
  padding:4px 10px;
  border-radius:4px;
  display:inline-block;
}
.hdr-left .co-title{
  font-size:22px;
  font-weight:700;
  color:#ffffff !important;
  letter-spacing:-0.2px;
  line-height:1.2;
}
.hdr-left .co-subtitle{
  font-size:8.5px;
  color:rgba(255,255,255,0.85) !important;
  text-transform:uppercase;
  letter-spacing:1.5px;
  margin-top:4px;
  font-weight:500;
}
.hdr-left .co-tax{
  font-size:9px;
  color:rgba(255,255,255,0.75) !important;
  margin-top:4px;
}

.hdr-right{
  text-align:right;
}
.doc-title{
  font-size:26px;
  font-weight:800;
  color:#ffffff !important;
  letter-spacing:0.5px;
  line-height:1;
}
.meta-box{
  margin-top:6px;
}
.meta-line{
  display:flex;
  justify-content:flex-end;
  gap:8px;
  font-size:9.5px;
  margin-top:2px;
}
.meta-k{color:rgba(255,255,255,0.75) !important;font-weight:400;}
.meta-v{color:#ffffff !important;font-weight:600;}
.status-tag{
  display:inline-block;
  margin-top:6px;
  padding:2px 10px;
  border-radius:12px;
  font-size:8px;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:0.5px;
  background:rgba(255,255,255,0.2);
  color:#ffffff !important;
  border:1px solid rgba(255,255,255,0.35);
}

/* ── INFO ROW ── */
.info-row{
  display:flex;
  gap:24px;
  margin:0 24px 18px;
}
.info-col{flex:1;}
.sec-label{
  font-size:8.5px;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:1.2px;
  color:var(--primary);
  margin-bottom:6px;
  border-bottom:1px solid var(--border-light);
  padding-bottom:3px;
}
.cust-name{
  font-size:15px;
  font-weight:600;
  color:var(--text-main);
  margin-bottom:2px;
}
.cust-sub{font-size:9.5px;color:var(--text-muted);margin-bottom:6px;}
.cust-addr-box{
  font-size:9.5px;
  color:var(--text-muted);
  margin-bottom:6px;
  line-height:1.4;
}
.ct-row{display:flex;gap:6px;margin-bottom:3px;font-size:9.5px;color:var(--text-main);}
.ct-k{font-weight:500;color:var(--text-muted);min-width:60px;}

.job-card{
  background:var(--bg-stripe);
  border:1px solid var(--border-light);
  border-radius:6px;
  padding:10px 14px;
}
.job-item{display:flex;justify-content:space-between;padding:3px 0;font-size:9.5px;border-bottom:1px dashed var(--border-light);}
.job-item:last-child{border:none;}
.job-k{color:var(--text-muted);font-weight:400;}
.job-v{font-weight:600;color:var(--text-main);}

/* ── MULTI-PAGE RESPONSIVE TABLE STYLING ── */
.pf-table{
  width:calc(100% - 48px);
  border-collapse:collapse;
  font-size:10px;
  margin:0 24px 10px;
  page-break-inside:auto;
}
.pf-table thead{
  display:table-header-group;
}
.pf-table tbody{
  display:table-row-group;
}
.pf-table tr{
  page-break-inside:avoid;
  page-break-after:auto;
}
.pf-table thead tr{background:var(--primary);}
.pf-table thead th{
  padding:9px 10px;
  color:#ffffff !important;
  font-size:8.5px;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:0.5px;
  text-align:left;
}
.pf-table thead th.r{text-align:right;}
.pf-table thead th.c{text-align:center;}
.pf-table tbody tr{border-bottom:1px solid var(--border-light);}
.pf-table tbody tr:nth-child(even){background:var(--bg-stripe);}
.pf-table tbody td{padding:8px 10px;color:var(--text-main);vertical-align:middle;font-weight:400;}
.pf-table tbody td.r{text-align:right;}
.pf-table tbody td.c{text-align:center;}
.desc-main{font-weight:500;color:var(--text-main);}
.desc-code{font-size:8.5px;color:var(--text-muted);margin-top:1px;}
.total-val{font-weight:600;color:var(--primary-dark);}

/* ── TOTALS ── */
.totals-wrap{display:flex;justify-content:flex-end;margin:6px 24px 18px;page-break-inside:avoid;}
.tot-card{width:240px;border:1px solid var(--border-light);border-radius:6px;overflow:hidden;}
.tot-line{display:flex;justify-content:space-between;padding:6px 12px;border-bottom:1px solid var(--border-light);font-size:10px;}
.tot-line:last-child{border:none;}
.tot-k{color:var(--text-muted);font-weight:400;}
.tot-v{font-weight:600;color:var(--text-main);}
.tot-line.grand{background:var(--primary);padding:9px 12px;}
.tot-line.grand .tot-k{color:#ffffff !important;font-size:10.5px;font-weight:600;}
.tot-line.grand .tot-v{color:#ffffff !important;font-size:13px;font-weight:700;}

/* ── NOTES ── */
{% if doc.notes %}
.notes-wrap{margin:0 24px 18px;page-break-inside:avoid;}
.notes-txt{font-size:9.5px;color:var(--text-muted);line-height:1.6;font-weight:400;}
{% endif %}

/* ── SIGNATURE ROW ── */
.sig-row{
  display:flex;
  justify-content:space-between;
  align-items:center;
  margin:24px 24px 16px;
  gap:24px;
  page-break-inside:avoid;
}
.thank-card{
  flex:1;
  background:var(--primary-light);
  border-left:3.5px solid var(--primary);
  border-radius:6px;
  padding:12px 16px;
}
.thank-title{
  font-size:12px;
  font-weight:600;
  color:var(--primary-dark);
  letter-spacing:0.2px;
}
.thank-sub{
  font-size:8.5px;
  color:var(--text-muted);
  margin-top:2px;
  line-height:1.4;
}
.sig-container{
  display:flex;
  gap:24px;
  align-items:flex-end;
}
.sig-box{
  text-align:center;
  min-width:160px;
}
.sig-space{
  height:36px;
}
.sig-line-bar{
  width:100%;
  border-top:1.5px solid var(--primary);
  margin-bottom:5px;
}
.sig-name{
  font-size:9.5px;
  font-weight:600;
  color:var(--text-main);
}
.sig-role{
  font-size:8px;
  color:var(--text-muted);
  font-weight:500;
  text-transform:uppercase;
  letter-spacing:0.5px;
  margin-top:1px;
}

/* ── FOOTER WITH EXPLICIT WHITE TEXT COLOR ── */
.pf-footer{
  background:var(--primary) !important;
  color:#ffffff !important;
  padding:14px 24px;
  border-radius:6px;
  display:flex;
  justify-content:space-between;
  align-items:flex-start;
  margin:20px 0 10px;
  font-size:9px;
  page-break-inside:avoid;
}
.pf-footer *, .pf-footer div, .pf-footer span, .pf-footer a{
  color:#ffffff !important;
}
.foot-left-block{
  line-height:1.6;
}
.foot-user-title{
  font-weight:600;
  color:#ffffff !important;
  font-size:9.5px;
}
.foot-date-text{
  font-size:8.5px;
  color:rgba(255,255,255,0.85) !important;
}
.foot-right-block{
  text-align:right;
  line-height:1.6;
}
.foot-co-name{
  font-weight:700;
  color:#ffffff !important;
  font-size:10px;
}

.keep{page-break-inside:avoid;}
@media print{
  .hdr, .pf-table thead, .tot-line.grand, .status-tag, .pf-footer, .thank-card{
    -webkit-print-color-adjust:exact;print-color-adjust:exact;
  }
}
</style>

<!-- HEADER -->
<div class="hdr">
  <div class="hdr-left">
    {% if co_logo %}
    <div><img src="{{ co_logo }}" alt="Oasis Logo" class="co-logo-img" /></div>
    {% else %}
    <div class="co-title">{{ co_name }}</div>
    {% endif %}
    <div class="co-subtitle">Job Management System</div>
    {% if co_tax %}<div class="co-tax">VAT Reg: {{ co_tax }}</div>{% endif %}
  </div>
  <div class="hdr-right">
    <div class="doc-title">JOB ORDER</div>
    <div class="meta-box">
      <div class="meta-line"><span class="meta-k">Job No:</span><span class="meta-v">{{ v(doc.name) }}</span></div>
      <div class="meta-line"><span class="meta-k">Date:</span><span class="meta-v">{{ fd(doc.date) }}</span></div>
      <div class="meta-line"><span class="meta-k">Type:</span><span class="meta-v">{{ v(doc.job_type) }}</span></div>
    </div>
    <div class="status-tag">{{ v(doc.status) }}</div>
  </div>
</div>

<!-- INFO ROW -->
<div class="info-row keep">
  <!-- Customer -->
  <div class="info-col">
    <div class="sec-label">Job To</div>
    <div class="cust-name">{{ v(doc.customer_name or doc.customer) }}</div>
    {% if doc.job_title %}<div class="cust-sub">{{ doc.job_title }}</div>{% endif %}

    {% if cust_addr_doc.get('address_line1') %}
    <div class="cust-addr-box">
      <div>{{ cust_addr_doc.address_line1 }}</div>
      {% if cust_addr_doc.get('address_line2') %}<div>{{ cust_addr_doc.address_line2 }}</div>{% endif %}
      <div>
        {% if cust_addr_doc.get('city') %}{{ cust_addr_doc.city }}{% endif %}
        {% if cust_addr_doc.get('state') %}, {{ cust_addr_doc.state }}{% endif %}
        {% if cust_addr_doc.get('country') %} - {{ cust_addr_doc.country }}{% endif %}
      </div>
    </div>
    {% endif %}

    {% if doc.customer_mobile %}<div class="ct-row"><span class="ct-k">Phone:</span><span>{{ doc.customer_mobile }}</span></div>{% endif %}
    {% if doc.vat_no %}<div class="ct-row"><span class="ct-k">VAT No:</span><span>{{ doc.vat_no }}</span></div>{% endif %}
    {% if doc.iqama_no %}<div class="ct-row"><span class="ct-k">IQAMA:</span><span>{{ doc.iqama_no }}</span></div>{% endif %}
  </div>
  <!-- Job Details -->
  <div class="info-col" style="flex:0 0 42%;">
    <div class="sec-label">Job Details</div>
    <div class="job-card">
      <div class="job-item"><span class="job-k">Priority</span><span class="job-v">{{ v(doc.priority) }}</span></div>
      <div class="job-item"><span class="job-k">Start Date</span><span class="job-v">{{ fd(doc.start_date) }}</span></div>
      {% if doc.expected_completion_date %}
      <div class="job-item"><span class="job-k">Expected By</span><span class="job-v">{{ fd(doc.expected_completion_date) }}</span></div>
      {% endif %}
      {% if doc.completion_date %}
      <div class="job-item"><span class="job-k">Completed</span><span class="job-v">{{ fd(doc.completion_date) }}</span></div>
      {% endif %}
    </div>
  </div>
</div>

<!-- TABLE WITH REPEATING HEADER & NATURAL PAGE BREAKS -->
{% if doc.items %}
<table class="pf-table">
  <thead>
    <tr>
      <th class="c" style="width:5%">No.</th>
      <th style="width:37%">Item Description</th>
      <th class="r" style="width:14%">Service Charge</th>
      <th class="r" style="width:10%">Gov Fee</th>
      <th class="r" style="width:9%">Extra</th>
      <th class="c" style="width:6%">Qty.</th>
      <th class="r" style="width:13%">Total</th>
    </tr>
  </thead>
  <tbody>
    {% for item in doc.items %}
    <tr>
      <td class="c" style="color:var(--text-muted);">{{ '%02d'%loop.index }}</td>
      <td>
        <div class="desc-main">{{ v(item.description) }}</div>
        {% if item.work_template %}<div class="desc-code">{{ item.work_template }}</div>{% endif %}
      </td>
      <td class="r">{{ fc(item.fee_price) }}</td>
      <td class="r">{{ fc(item.surcharge) }}</td>
      <td class="r">{{ fc(item.extra) }}</td>
      <td class="c">{{ item.job_qty or 1 }}</td>
      <td class="r total-val">{{ fc(item.total) }}</td>
    </tr>
    {% endfor %}
  </tbody>
</table>

<!-- TOTALS -->
<div class="totals-wrap">
  <div class="tot-card">
    {% if doc.gross_amount %}
    <div class="tot-line"><span class="tot-k">Subtotal:</span><span class="tot-v">{{ fc(doc.gross_amount) }}</span></div>
    {% endif %}
    {% if doc.discount %}
    <div class="tot-line"><span class="tot-k">Discount:</span><span class="tot-v">- {{ fc(doc.discount) }}</span></div>
    {% endif %}
    <div class="tot-line grand"><span class="tot-k">Total:</span><span class="tot-v">{{ fc(doc.net_amount) }}</span></div>
  </div>
</div>
{% endif %}

<!-- NOTES -->
{% if doc.notes %}
<div class="notes-wrap keep">
  <div class="sec-label">Notes &amp; Remarks</div>
  <div class="notes-txt">{{ doc.notes | striptags }}</div>
</div>
{% endif %}

<!-- SIGNATURE ROW -->
<div class="sig-row keep">
  <div class="thank-card">
    <div class="thank-title">Thank you for your business!</div>
    <div class="thank-sub">We appreciate your partnership and look forward to working with you again.</div>
  </div>
  <div class="sig-container">
    <div class="sig-box">
      <div class="sig-space"></div>
      <div class="sig-line-bar"></div>
      <div class="sig-name">{{ co_name }}</div>
      <div class="sig-role">Authorized Signatory</div>
    </div>
  </div>
</div>

<!-- FOOTER WITH EXPLICIT WHITE TEXT COLOR -->
<div class="pf-footer keep">
  <!-- Left: Logged In User Info -->
  <div class="foot-left-block">
    <div>Printed / Prepared By: <span class="foot-user-title">{{ current_user_name }}</span></div>
    <div class="foot-date-text">{{ frappe.format(frappe.utils.now(), {'fieldtype':'Datetime'}) }}</div>
  </div>

  <!-- Right: Company Address & Contact -->
  <div class="foot-right-block">
    <div class="foot-co-name">{{ co_name }}</div>
    {% if addr_doc.get('address_line1') %}<div>{{ addr_doc.address_line1 }}</div>{% endif %}
    {% if addr_doc.get('address_line2') %}<div>{{ addr_doc.address_line2 }}</div>{% endif %}
    <div>
      {% if addr_doc.get('city') %}{{ addr_doc.city }}{% endif %}
      {% if addr_doc.get('state') %}, {{ addr_doc.state }}{% endif %}
      {% if addr_doc.get('country') %} - {{ addr_doc.country }}{% endif %}
    </div>
    {% if co_phone or co_email %}
    <div style="margin-top:2px;">
      {% if co_phone %}<span>Ph: {{ co_phone }}</span>{% endif %}
      {% if co_phone and co_email %} | {% endif %}
      {% if co_email %}<span>{{ co_email }}</span>{% endif %}
    </div>
    {% endif %}
  </div>
</div>
